{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/before-after.json
    Two columns that set life without the product against life with it, point by point. Axes: layout (cards: two cards, rows: one row per point), icons (show, hide), tone, density.
    Props (p): id, title, points, labels, layout, icons, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_points = ($p['points'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'cards')}
{var $v_icons = ($p['icons'] ?? 'show')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_21}
  {if ui_t(ui_eq($v_layout, 'cards'))}
    {capture $c_13}
      {capture $c_6}
        {capture $c_5}
          {capture $c_1}
            {=ui_text(ui_get($v_labels, ['before']))}
          {/capture}
          {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'xl', 'Weight' => 'bold'], 'children' => $c_1])|noescape}
          {capture $c_4}
            {foreach ui_l($v_points) as $v_p}
              {capture $c_3}
                {if ui_t(ui_eq($v_icons, 'show'))}
                  {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'x', 'Size' => 16, 'Class' => 'h-lh shrink-0 text-sm']])|noescape}
                {/if}
                {capture $c_2}
                  {=ui_text(ui_get($v_p, ['before']))}
                {/capture}
                {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm'], 'children' => $c_2])|noescape}
              {/capture}
              {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'flex items-start gap-4', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_3])|noescape}
            {/foreach}
          {/capture}
          {=ui_include('ui/list/list.latte', ['p' => ['Class' => 'm-0 flex list-none flex-col gap-4 p-0'], 'children' => $c_4])|noescape}
        {/capture}
        {=ui_include('ui/card/card-content.latte', ['p' => ['Class' => 'flex flex-col gap-4'], 'children' => $c_5])|noescape}
      {/capture}
      {=ui_include('ui/card/card.latte', ['p' => ['Variant' => 'muted', 'Class' => ui_s(ui_cnv(['h-full', (ui_t(ui_eq($v_density, 'compact')) ? 'gap-4 p-4' : '')])), 'Attrs' => ui_attrs(['data-testid', 'side', 'data-side', 'before'])], 'children' => $c_6])|noescape}
      {capture $c_12}
        {capture $c_11}
          {capture $c_7}
            {=ui_text(ui_get($v_labels, ['after']))}
          {/capture}
          {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'xl', 'Weight' => 'bold'], 'children' => $c_7])|noescape}
          {capture $c_10}
            {foreach ui_l($v_points) as $v_p}
              {capture $c_9}
                {if ui_t(ui_eq($v_icons, 'show'))}
                  {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'check', 'Size' => 16, 'Class' => 'h-lh shrink-0 text-sm']])|noescape}
                {/if}
                {capture $c_8}
                  {=ui_text(ui_get($v_p, ['after']))}
                {/capture}
                {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm'], 'children' => $c_8])|noescape}
              {/capture}
              {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'flex items-start gap-4', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_9])|noescape}
            {/foreach}
          {/capture}
          {=ui_include('ui/list/list.latte', ['p' => ['Class' => 'm-0 flex list-none flex-col gap-4 p-0'], 'children' => $c_10])|noescape}
        {/capture}
        {=ui_include('ui/card/card-content.latte', ['p' => ['Class' => 'flex flex-col gap-4'], 'children' => $c_11])|noescape}
      {/capture}
      {=ui_include('ui/card/card.latte', ['p' => ['Variant' => 'default', 'Class' => ui_s(ui_cnv(['h-full', (ui_t(ui_eq($v_density, 'compact')) ? 'gap-4 p-4' : '')])), 'Attrs' => ui_attrs(['data-testid', 'side', 'data-side', 'after'])], 'children' => $c_12])|noescape}
    {/capture}
    {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => '1-2', 'Class' => 'items-stretch gap-4', 'Attrs' => ui_attrs(['data-testid', 'sides'])], 'children' => $c_13])|noescape}
  {else}
    {capture $c_20}
      {foreach ui_l($v_points) as $v_p}
        {capture $c_19}
          {capture $c_14}
            {=ui_text(ui_get($v_p, ['title']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'base', 'Weight' => 'semibold'], 'children' => $c_14])|noescape}
          {capture $c_16}
            {if ui_t(ui_eq($v_icons, 'show'))}
              {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'x', 'Size' => 16, 'Class' => 'h-lh shrink-0 text-sm text-muted-foreground']])|noescape}
            {/if}
            {capture $c_15}
              {=ui_text(ui_get($v_p, ['before']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_15])|noescape}
          {/capture}
          {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'start'], 'children' => $c_16])|noescape}
          {capture $c_18}
            {if ui_t(ui_eq($v_icons, 'show'))}
              {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'check', 'Size' => 16, 'Class' => 'h-lh shrink-0 text-sm text-primary']])|noescape}
            {/if}
            {capture $c_17}
              {=ui_text(ui_get($v_p, ['after']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_17])|noescape}
          {/capture}
          {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'start'], 'children' => $c_18])|noescape}
        {/capture}
        {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => '1-3', 'Class' => ui_s(ui_cnv(['items-center gap-4', 'rounded bg-card inset-ring inset-ring-border p-4'])), 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_19])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'rows'])], 'children' => $c_20])|noescape}
  {/if}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_21])|noescape}
